      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, clientId: Number(clientId), status }),
    });
    if (res.ok) {
      setName('');
      setClientId('');
      setStatus('ACTIVE');
      await loadProjects();
    }
  }

