        onClick={() => setShowArchived((shown) => !shown)}
      >
        {showArchived ? 'Hide archived' : 'Show archived'}
      </button>

      <select
        data-testid="project-status-filter"
        value={statusFilter}
        onChange={(e) => setStatusFilter(e.target.value)}
      >
        <option value="">All statuses</option>
        {PROJECT_STATUSES.map((value) => (
          <option key={value} value={value}>
            {value}
          </option>
        ))}
      </select>

      <select
        data-testid="project-tag-filter"
        value={tagFilter}
        onChange={(e) => setTagFilter(e.target.value)}
      >
        <option value="">All tags</option>
        {tags.map((tag) => (
          <option key={tag.id} value={tag.id}>
            {tag.name}
          </option>
        ))}
      </select>

      {projects.length === 0 ? (
        <p data-testid="projects-empty">No jobs yet.</p>
      ) : (
        <table data-testid="projects-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Client</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {projects.map((project) => (
              <tr key={project.id} data-testid={`project-row-${project.id}`}>
                <td data-testid="project-name">{project.name}</td>
                <td data-testid="project-client">{project.clientName}</td>
                <td data-testid="project-status">{project.status}</td>
                <td>
                  <button
                    data-testid={`project-open-${project.id}`}
                    type="button"
                    onClick={() => setOpenProjectId(project.id)}
                  >
                    Open
                  </button>
                  <button
                    data-testid={`project-archive-${project.id}`}
                    type="button"
                    onClick={() => void onArchive(project.id)}
                  >
                    Archive
                  </button>
                  <button
                    data-testid={`project-delete-${project.id}`}
                    type="button"
                    onClick={() => void onDelete(project.id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {openProjectId !== null && <ProjectDetail projectId={openProjectId} />}
    </section>
  );
}

import { useEffect, useRef, useState, type FormEvent } from 'react';
import { ProjectDetail } from './ProjectDetail';

// This arm's convention: the page component owns the feature's state, data loading and layout.
// A project belongs to a client; the list shows the client's NAME, and the form's client picker is
// a <select> whose option values are client ids.
type Client = { id: number; name: string; email: string };
type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';
type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  status: ProjectStatus;
  code: string;
};
type Tag = { id: number; name: string };

// A project's lifecycle status: the work is active, paused on hold, or finished.
const PROJECT_STATUSES: ProjectStatus[] = ['ACTIVE', 'ON_HOLD', 'FINISHED'];

export function ProjectsPage() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [clients, setClients] = useState<Client[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [name, setName] = useState('');
  const [clientId, setClientId] = useState('');
  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
  const [code, setCode] = useState('');
  const [codeError, setCodeError] = useState<string | null>(null);
  const [tagFilter, setTagFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [openProjectId, setOpenProjectId] = useState<number | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  // Changing the status and tag filters in quick succession fires two overlapping fetches; without a
  // guard the earlier (less-narrowed) response can land last and clobber the narrower one. Tag each
  // request and apply only the latest, so combining both filters at once settles on the right list.
  const loadSeq = useRef(0);

  async function loadProjects() {
    const seq = ++loadSeq.current;
    const params = new URLSearchParams();
    if (showArchived) {
      params.set('includeArchived', 'true');
    }
    if (tagFilter) {
      params.set('tagId', tagFilter);
    }
    if (statusFilter) {
      params.set('status', statusFilter);
    }
    const query = params.toString();
    const res = await fetch(query ? `/api/projects?${query}` : '/api/projects');
    if (res.ok && seq === loadSeq.current) {
      setProjects(await res.json());
    }
  }

  async function loadClients() {
    const res = await fetch('/api/clients');
    if (res.ok) {
      setClients(await res.json());
    }
  }

  async function loadTags() {
    const res = await fetch('/api/tags');
    if (res.ok) {
      setTags(await res.json());
    }
  }

  useEffect(() => {
    void loadClients();
    void loadTags();
  }, []);

  // Load the list on mount and re-fetch whenever the archived toggle flips or the tag filter
  // changes, so the list always reflects them. This is the single owner of the projects fetch:
  // keeping it the only caller avoids a stray initial request resolving after a filtered one and
  // overwriting the narrowed list.
  useEffect(() => {
    void loadProjects();
  }, [showArchived, tagFilter, statusFilter]);

  async function onArchive(id: number) {
    const res = await fetch(`/api/projects/${id}/archive`, { method: 'POST' });
    if (res.ok) {
      if (openProjectId === id) {
        setOpenProjectId(null);
      }
      await loadProjects();
    }
  }

  async function onDelete(id: number) {
    const res = await fetch(`/api/projects/${id}/delete`, { method: 'POST' });
    if (res.ok) {
      if (openProjectId === id) {
        setOpenProjectId(null);
      }
      await loadProjects();
    }
  }

  async function onSubmit(event: FormEvent) {
    event.preventDefault();
    setCodeError(null);
    const res = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, clientId: Number(clientId), status, code }),
    });
    if (res.ok) {
      // No two jobs can share a reference code: the server rejects the duplicate and adds no row.
      const result = (await res.json()) as { codeInUse?: boolean };
      if (result.codeInUse) {
        setCodeError('That code is already in use.');
        return;
      }
      setName('');
      setClientId('');
      setStatus('ACTIVE');
      setCode('');
      setCodeError(null);
      await loadProjects();
    }
  }

  return (
    <section data-testid="projects-page">
      <h1>Jobs</h1>

      <form data-testid="project-form" onSubmit={onSubmit}>
        <input
          data-testid="project-form-name"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <select
          data-testid="project-form-client"
          value={clientId}
          onChange={(e) => setClientId(e.target.value)}
        >
          <option value="">Select a client</option>
          {clients.map((client) => (
            <option key={client.id} value={client.id}>
              {client.name}
            </option>
          ))}
        </select>
        <select
          data-testid="project-form-status"
          value={status}
          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
        >
          {PROJECT_STATUSES.map((value) => (
            <option key={value} value={value}>
              {value}
            </option>
          ))}
        </select>
        <input
          data-testid="project-form-code"
          placeholder="Code"
          value={code}
          onChange={(e) => setCode(e.target.value)}
        />
        {codeError && <p data-testid="project-form-code-error">{codeError}</p>}
        <button data-testid="project-form-submit" type="submit">
          Add job
        </button>
      </form>

      <button
        data-testid="projects-show-archived"
        type="button"
        onClick={() => setShowArchived((shown) => !shown)}
      >
        {showArchived ? 'Hide archived' : 'Show archived'}
      </button>

      <select
        data-testid="project-status-filter"
        value={statusFilter}
        onChange={(e) => setStatusFilter(e.target.value)}
      >
        <option value="">All statuses</option>
        {PROJECT_STATUSES.map((value) => (
          <option key={value} value={value}>
            {value}
          </option>
        ))}
      </select>

      <select
        data-testid="project-tag-filter"
        value={tagFilter}
        onChange={(e) => setTagFilter(e.target.value)}
      >
        <option value="">All tags</option>
        {tags.map((tag) => (
          <option key={tag.id} value={tag.id}>
            {tag.name}
          </option>
        ))}
      </select>

      {projects.length === 0 ? (
        <p data-testid="projects-empty">No jobs yet.</p>
      ) : (
        <table data-testid="projects-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Code</th>
              <th>Client</th>
              <th>Status</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {projects.map((project) => (
              <tr key={project.id} data-testid={`project-row-${project.id}`}>
                <td data-testid="project-name">{project.name}</td>
                <td data-testid="project-client">{project.clientName}</td>
                <td data-testid="project-status">{project.status}</td>
                <td>
                  <button
                    data-testid={`project-open-${project.id}`}
                    type="button"
                    onClick={() => setOpenProjectId(project.id)}
                  >
                    Open
                  </button>
                  <button
                    data-testid={`project-archive-${project.id}`}
                    type="button"
                    onClick={() => void onArchive(project.id)}
                  >
                    Archive
                  </button>
                  <button
                    data-testid={`project-delete-${project.id}`}
                    type="button"
                    onClick={() => void onDelete(project.id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {openProjectId !== null && <ProjectDetail projectId={openProjectId} />}
    </section>
  );
}
